      "pergunta": "QUESTÃO 133) No ar que respiramos existem os chamados “gases inertes”. Trazem curiosos nomes gregos, que signiﬁcam “o Novo”, “o Oculto”, “o Inativo”. E de fato são de tal modo inertes, tão satisfeitos em sua condição, que não interferem em nenhuma reação química, não se combinam com nenhum outro elemento e justamente por esse motivo ﬁcaram sem ser observados durante séculos: só em 1962 um químico, depois de longos e engenhosos esforços, conseguiu forçar “o Estrangeiro” (o xenônio) a combinar-se fugazmente com o flúor ávido e vivaz, e a façanha pareceu tão extraordinária que lhe foi conferido o Prêmio Nobel.\nQual propriedade do flúor justiﬁca sua escolha como reagente para o processo mencionado?",
