      "id": 71,
      "pergunta": "QUESTÃO 71) Os biocombustíveis de primeira geração são derivados da soja, milho e cana-de-açúcar e sua produção ocorre através da fermentação. Biocombustíveis derivados de material celulósico ou biocombustíveis de segunda geração — coloquialmente chamados de “gasolina de capim” — são aqueles produzidos a partir de resíduos de madeira (serragem, por exemplo), talos de milho, palha de trigo ou capim de crescimento rápido e se apresentam como uma alternativa para os problemas enfrentados pelos de primeira geração, já que as matérias-primas são baratas e abundantes.\nDALE, B. E.; HUBER, G. W. Gasolina de capim e outros vegetais. O texto mostra um dos pontos de vista a respeito do uso dos biocombustíveis na atualidade, os quais",
